package com.nickuc.login.auth.login;

import com.nickuc.login.config.PasswordHashContainer;
import org.bouncycastle.jce.provider.BouncyCastleProvider;
import org.bouncycastle.openpgp.PGPObjectFactory;
import org.bouncycastle.openpgp.PGPPublicKey;
import org.bouncycastle.openpgp.PGPPublicKeyRingCollection;
import org.bouncycastle.openpgp.PGPSignature;
import org.bouncycastle.openpgp.PGPSignatureList;
import org.bouncycastle.openpgp.PGPUtil;
import org.bouncycastle.openpgp.operator.jcajce.JcaKeyFingerprintCalculator;
import org.bouncycastle.openpgp.operator.jcajce.JcaPGPContentVerifierBuilderProvider;
import java.io.BufferedInputStream;
import java.io.ByteArrayInputStream;
import java.io.File;
import java.io.InputStream;
import java.nio.file.Files;
import java.util.Base64;

public class LoginFlow {
   private static final byte[] values = Base64.getDecoder()
      .decode(
         ""
      );
   private static final byte[] activeValues = Base64.getDecoder()
      .decode(
         ""
      );

   public static boolean validateState(File instance, InputStream target) {
      BouncyCastleProvider input = new BouncyCastleProvider();
      PGPPublicKeyRingCollection output = new PGPPublicKeyRingCollection(new ByteArrayInputStream(values), new JcaKeyFingerprintCalculator());
      PGPPublicKeyRingCollection context = new PGPPublicKeyRingCollection(new ByteArrayInputStream(activeValues), new JcaKeyFingerprintCalculator());
      PGPObjectFactory data = new PGPObjectFactory(PGPUtil.getDecoderStream(target), new JcaKeyFingerprintCalculator());
      Object value = data.nextObject();
      PGPSignatureList result = value instanceof PGPSignatureList ? (PGPSignatureList)value : (PGPSignatureList)data.nextObject();
      if (result.isEmpty()) {
         return false;
      }

      PGPSignature request = result.get(0);
      PGPPublicKey response = output.getPublicKey(request.getKeyID());
      if (response == null) {
         response = context.getPublicKey(request.getKeyID());
      }

      if (response == null) {
         throw new IllegalArgumentException("Public key not found in " + instance.getName() + " file!");
      }

      request.init(new JcaPGPContentVerifierBuilderProvider().setProvider(input), response);
      BufferedInputStream source = new BufferedInputStream(Files.newInputStream(instance.toPath()));

      int entry;
      try {
         while ((entry = source.read()) >= 0) {
            request.update((byte)entry);
         }
      } catch (Throwable element) {
         try {
            source.close();
         } catch (Throwable item) {
            element.addSuppressed(item);
         }

         throw element;
      }

      source.close();
      return request.verify();
   }

   public static boolean validateState(File instance, File target) {
      try {
         return validateState(instance, Files.newInputStream(target.toPath()));
      } catch (Throwable output) {
         PasswordHashContainer.processMessage("Unable to verify " + instance.getAbsolutePath() + " signature!", output);
         return false;
      }
   }

   public static boolean hasState(File instance, InputStream target) {
      try {
         return validateState(instance, target);
      } catch (Throwable output) {
         PasswordHashContainer.processMessage("Unable to verify " + instance.getAbsolutePath() + " signature!", output);
         return false;
      }
   }
}
